package com.example.jobfinderapp.adapters;
import android.view.*;import android.widget.*;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.example.jobfinderapp.R;import com.example.jobfinderapp.models.Project;import java.util.*;
public class ProjectAdapter extends RecyclerView.Adapter<ProjectAdapter.H>{public interface Listener{void onEdit(Project p);void onDelete(Project p);void onOpenGithub(Project p);void onOpenDemo(Project p);}private final List<Project> items=new ArrayList<>();private final Listener listener;public ProjectAdapter(Listener l){listener=l;}public void update(List<Project> v){items.clear();items.addAll(v);notifyDataSetChanged();}@NonNull public H onCreateViewHolder(@NonNull ViewGroup p,int t){return new H(LayoutInflater.from(p.getContext()).inflate(R.layout.item_project,p,false));}public void onBindViewHolder(@NonNull H h,int p){Project x=items.get(p);h.name.setText(x.getProjectName());h.role.setText(x.getRole());h.period.setText((x.getStartDate()==null?"":x.getStartDate())+" – "+(x.getEndDate()==null||x.getEndDate().trim().isEmpty()?"Hiện tại":x.getEndDate()));h.edit.setOnClickListener(v->listener.onEdit(x));h.delete.setOnClickListener(v->listener.onDelete(x));}public int getItemCount(){return items.size();}static class H extends RecyclerView.ViewHolder{TextView name,role,period;ImageButton edit,delete;H(View v){super(v);name=v.findViewById(R.id.tvProjectName);role=v.findViewById(R.id.tvProjectRole);period=v.findViewById(R.id.tvProjectPeriod);edit=v.findViewById(R.id.btnEditProject);delete=v.findViewById(R.id.btnDeleteProject);}}}
